import json
import sys


def _load_value(memory, buf, addr, width):
    """Read width bytes starting at addr. For each byte, the youngest buffered
    store in the same thread covering that byte wins, else shared memory."""
    val = 0
    for i in range(width):
        a = addr + i
        b = None
        for (sa, sw, sv) in reversed(buf):
            if sa <= a < sa + sw:
                b = (sv >> (8 * (a - sa))) & 0xFF
                break
        if b is None:
            b = memory[a]
        val |= b << (8 * i)
    return val


def _write_value(ml, addr, width, value):
    for i in range(width):
        ml[addr + i] = (value >> (8 * i)) & 0xFF


def solve(request):
    mem0 = tuple(request["memory"])
    instrs = [tuple(tuple(ins) for ins in th) for th in request["threads"]]
    n = len(instrs)

    start = (mem0, tuple((0, (), ()) for _ in range(n)))
    outcomes = set()
    visited = {start}
    stack = [start]

    while stack:
        memory, threads = stack.pop()

        if all(threads[i][0] == len(instrs[i]) and not threads[i][1]
               for i in range(n)):
            outcomes.add((tuple(t[2] for t in threads), memory))
            continue

        for i in range(n):
            pc, buf, obs = threads[i]
            ins_list = instrs[i]
            if pc < len(ins_list):
                ins = ins_list[pc]
                op = ins[0]
                if op == "store":
                    _, addr, width, value = ins
                    nt = (pc + 1, buf + ((addr, width, value),), obs)
                elif op == "load":
                    _, addr, width = ins
                    v = _load_value(memory, buf, addr, width)
                    nt = (pc + 1, buf, obs + (v,))
                elif op == "fence":
                    if buf:
                        continue
                    nt = (pc + 1, buf, obs)
                elif op == "xchg":
                    if buf:
                        continue
                    _, addr, width, value = ins
                    v = _load_value(memory, buf, addr, width)
                    ml = list(memory)
                    _write_value(ml, addr, width, value)
                    memory = tuple(ml)
                    nt = (pc + 1, buf, obs + (v,))
                else:
                    continue
                ns = (memory, threads[:i] + (nt,) + threads[i + 1:])
                if ns not in visited:
                    visited.add(ns)
                    stack.append(ns)

        for i in range(n):
            pc, buf, obs = threads[i]
            if buf:
                addr, width, value = buf[0]
                ml = list(memory)
                _write_value(ml, addr, width, value)
                nt = (pc, buf[1:], obs)
                ns = (tuple(ml), threads[:i] + (nt,) + threads[i + 1:])
                if ns not in visited:
                    visited.add(ns)
                    stack.append(ns)

    out = []
    for reads, memory in outcomes:
        out.append({"reads": [list(r) for r in reads], "memory": list(memory)})
    return {"outcomes": out}


if __name__ == "__main__":
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        print(json.dumps(solve(json.loads(line))))
